package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import java.util.Iterator;
import org.apache.commons.math.MathRuntimeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayRealVector.getLInfNorm().
 * 
 * Note: The implementation provided in the prompt:
 * max += Math.max(max, Math.abs(a));
 * is mathematically unusual for an L-infinity norm (which should be max(|a_i|)),
 * but these tests validate the logic as provided in the snippet.
 */
public class ArrayRealVector_getLInfNorm_TriageGen4Test {

    @Test
    public void testGetLInfNorm_EmptyVector() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{});
        // max starts at 0, loop doesn't execute
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_AllZeros() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{0.0, 0.0, 0.0});
        Assert.assertEquals(0.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_SinglePositiveValue() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{5.0});
        // max = 0; max += Math.max(0, 5.0) -> max = 5.0
        Assert.assertEquals(5.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_SingleNegativeValue() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{-5.0});
        // max = 0; max += Math.max(0, |-5.0|) -> max = 5.0
        Assert.assertEquals(5.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MultipleValuesIncreasing() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{1.0, 2.0, 3.0});
        // Iteration 1: max = 0 + max(0, 1) = 1
        // Iteration 2: max = 1 + max(1, 2) = 3
        // Iteration 3: max = 3 + max(3, 3) = 6
        Assert.assertEquals(6.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MultipleValuesDecreasing() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{3.0, 2.0, 1.0});
        // Iteration 1: max = 0 + max(0, 3) = 3
        // Iteration 2: max = 3 + max(3, 2) = 6
        // Iteration 3: max = 6 + max(6, 1) = 12
        Assert.assertEquals(12.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_MixedSigns() {
        ArrayRealVector vector = new ArrayRealVector(new double[]{1.0, -5.0, 2.0});
        // Iteration 1: max = 0 + max(0, 1) = 1
        // Iteration 2: max = 1 + max(1, 5) = 6
        // Iteration 3: max = 6 + max(6, 2) = 12
        Assert.assertEquals(12.0, vector.getLInfNorm(), 1e-10);
    }

    @Test
    public void testGetLInfNorm_LargeValues() {
        double val = 1e10;
        ArrayRealVector vector = new ArrayRealVector(new double[]{val, val});
        // Iteration 1: max = 0 + 1e10 = 1e10
        // Iteration 2: max = 1e10 + max(1e10, 1e10) = 2e10
        Assert.assertEquals(2e10, vector.getLInfNorm(), 1e-2);
    }
}
